CREATE TABLE "User"("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"emailVerified" BOOLEAN NOT NULL DEFAULT false,"image" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Session"("id" TEXT PRIMARY KEY,"expiresAt" TIMESTAMP(3) NOT NULL,"token" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"ipAddress" TEXT,"userAgent" TEXT,"userId" TEXT NOT NULL);CREATE UNIQUE INDEX "Session_token_key" ON "Session"("token");CREATE INDEX "Session_userId_idx" ON "Session"("userId");ALTER TABLE "Session" ADD CONSTRAINT "Session_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "Account"("id" TEXT PRIMARY KEY,"accountId" TEXT NOT NULL,"providerId" TEXT NOT NULL,"userId" TEXT NOT NULL,"accessToken" TEXT,"refreshToken" TEXT,"idToken" TEXT,"accessTokenExpiresAt" TIMESTAMP(3),"refreshTokenExpiresAt" TIMESTAMP(3),"scope" TEXT,"password" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);CREATE INDEX "Account_userId_idx" ON "Account"("userId");ALTER TABLE "Account" ADD CONSTRAINT "Account_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "Verification"("id" TEXT PRIMARY KEY,"identifier" TEXT NOT NULL,"value" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);CREATE INDEX "Verification_identifier_idx" ON "Verification"("identifier");
CREATE TABLE "Bill"("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"billType" TEXT NOT NULL DEFAULT 'standard',"month" TEXT NOT NULL,"billDate" TEXT NOT NULL DEFAULT '',"units" DOUBLE PRECISION NOT NULL,"importedUnits" DOUBLE PRECISION,"exportedUnits" DOUBLE PRECISION,"billedConsumption" DOUBLE PRECISION,"bankOpening" DOUBLE PRECISION,"bankClosing" DOUBLE PRECISION,"amount" DOUBLE PRECISION NOT NULL,"netPayable" DOUBLE PRECISION,"consumerNumber" TEXT,"originalName" TEXT,"objectKey" TEXT NOT NULL,"sha256" TEXT NOT NULL,"uploadedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE UNIQUE INDEX "Bill_userId_sha256_key" ON "Bill"("userId","sha256");CREATE INDEX "Bill_userId_month_idx" ON "Bill"("userId","month");CREATE INDEX "Bill_userId_uploadedAt_idx" ON "Bill"("userId","uploadedAt");ALTER TABLE "Bill" ADD CONSTRAINT "Bill_userId_fkey" FOREIGN KEY("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
